INSERT INTO briefings (kind, title, summary, body, url, cover_key, cover_url, author_id, published, published_at, status, submitted_by, category_id, created_at, updated_at) VALUES
  ('link', 'It''s Ok to Have a Favorite Marketing Channel', 'Diversification is good. Pretending every channel matters equally isn''t. Why playing favorites — for the right reasons — beats spreading thin across every available platform.', '', 'https://www.pitchblende.net/insights/its-ok-have-favorite-marketing-channel', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630cb2ce847e4ace6e5bd_6a1630b4eab6335a6006dc1d_blog-favorite-marketing-channel.jpeg', NULL, 1, 1707868800000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'Marketing Starts At the Top of the Funnel - Pulling at the Heartstrings', 'Marketing starts at the top of the funnel. It''s more than just convincing customers to open their wallets, it''s about touching their hearts and influencing their minds.', '', 'https://www.pitchblende.net/insights/the-top-of-funnel-is-where-marketing-starts', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630a4e2809876cec90b78_6a16305fdab18a92bb821f9b_blog-top-of-funnel-marketing.jpeg', NULL, 1, 1710892800000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'Omnichannel Marketing & The Value of Brand to Demand', 'Let''s talk about the value of building your brand.', '', 'https://www.pitchblende.net/insights/the-value-of-your-brand-why-you-measure-it', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630a4e2809876cec90b85_6a16305ed72195b1e596ee53_blog-omnichannel-brand-to-demand.jpeg', NULL, 1, 1711497600000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'The Death of the Click: Why SEO Alone Won''t Power Your Brand', 'Zero-click search is the new normal. If your strategy still depends on traffic to your site, you''re optimizing for a behavior that''s quietly disappearing.', '', 'https://www.pitchblende.net/insights/the-death-of-the-click-why-seo-alone-wont-power-your-brand', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630a4e2809876cec90b88_6a16305cf4ed00ecd48bce2f_blog-death-of-the-click.jpeg', NULL, 1, 1763078400000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'technology'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'Welcome to AI-First Google: 2025''s Biggest Shifts, Explained', '2025 completely reshaped the Google ecosystem.', '', 'https://www.pitchblende.net/insights/welcome-to-ai-first-google-2025s-biggest-shifts-explained', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630a4e2809876cec90b81_6a16305199aa262953e5d1a3_blog-ai-first-google.jpeg', NULL, 1, 1765238400000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'technology'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'What''s Next in 2026 for AEO (Answer Engine Optimization)', 'Answer engines don''t crawl — they synthesize. A look at what changes in 2026 for brands that need to show up where the answers get generated, not just where the links live.', '', 'https://www.pitchblende.net/insights/whats-next-in-2026-for-aeo-answer-engine-optimization', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630a4e2809876cec90b8c_6a16304fc0078362a4c99ef8_blog-whats-next-aeo-2026.png', NULL, 1, 1767657600000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'technology'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', '2025 Timeline of Google AI Updates', 'A month-by-month look at how Google quietly rebuilt search around AI in 2025 — and what each shift meant for the brands trying to keep up.', '', 'https://www.pitchblende.net/insights/2025-timeline-of-google-ai-updates', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630a5e2809876cec90b95_6a16304d983b700f4aa28155_blog-google-ai-timeline-2025.png', NULL, 1, 1768348800000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'technology'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'Why Now Is the Time to Kickstart Your ABM Strategy for 2026', 'Account-based marketing only works if the foundation is laid before you need results. Why Q1 is the window to build the list, the signal, and the alignment that pays off all year.', '', 'https://www.pitchblende.net/insights/why-now-is-the-time-to-kickstart-your-abm-strategy-for-2026', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630a5e2809876cec90b98_6a16304a5972daabbeeef431_blog-abm-strategy-2026.png', NULL, 1, 1768953600000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'What Performance Marketing Actually Means in 2026', 'Performance marketing has been reduced to a handful of surface-level metrics, but in 2026, those metrics are telling an incomplete story.', '', 'https://www.pitchblende.net/insights/what-performance-marketing-actually-means-in-2026', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630a4e2809876cec90b90_6a163047b8c73358bc954c5b_blog-performance-marketing-2026.png', NULL, 1, 1769558400000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'Creative is the New Targeting', 'No longer is the strategy of audience + bid + moment = return enough. In an era of AI and automation, how do you still manage to win?', '', 'https://www.pitchblende.net/insights/creative-is-the-new-targeting', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630a4e2809876cec90b7e_6a16303799aa262953e5cc4e_blog-creative-is-the-new-targeting.png', NULL, 1, 1770076800000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'Ad Automation: What to Trust and What to Control', 'Automation has officially moved from being an optional advantage to a campaign necessity within platforms like Google Ads and LinkedIn Ads.', '', 'https://www.pitchblende.net/insights/ad-automation-what-to-trust-and-what-to-control', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630cc2ce847e4ace6e5ce_6a163036ed4958694a59ea90_blog-ad-automation.png', NULL, 1, 1770681600000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'Attribution in Practice', 'There isn''t a tracking issue. There is a measurement model issue. Assisted conversions and attribution close the gap.', '', 'https://www.pitchblende.net/insights/attribution-in-practice', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630cc2ce847e4ace6e5cb_6a1630343ec94dff3be7b2cc_blog-attribution-in-practice.png', NULL, 1, 1771286400000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', '5 Tips for Building a Real Growth Engine', 'Growth doesn''t come from what you pull out of a campaign, it comes from what you put into the system around it.', '', 'https://www.pitchblende.net/insights/5-tips-for-building-a-real-growth-engine', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630cc2ce847e4ace6e5c8_6a163033b3647bdaa8d81c6d_blog-5-tips-growth-engine.png', NULL, 1, 1771977600000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'Relevance Over Recency: The New LinkedIn Distribution Model', 'LinkedIn is one of the few environments where brand, demand, trust, and expertise are built in front of the audience simultaneously.', '', 'https://www.pitchblende.net/insights/relevance-over-recency-the-new-linkedin-distribution-model', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630cc2ce847e4ace6e5d3_6a16303159cfcbf92b1ee3d1_blog-relevance-over-recency.png', NULL, 1, 1772409600000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'technology'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'The Mechanics: How Does LinkedIn Actually Distribute Content', 'LinkedIn''s algorithm rewards what feels counterintuitive: relevance over recency, engagement quality over volume. A look under the hood at what actually moves your post.', '', 'https://www.pitchblende.net/insights/the-mechanics-how-does-linkedin-actually-distribute-content', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630cc2ce847e4ace6e5e4_6a1630230bf3d7c5de606eaf_blog-linkedin-distribute-content.png', NULL, 1, 1773100800000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'technology'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'The Cost of Treating Marketing Like a Nice-to-Have', 'Marketing is one of the only functions in a business that becomes more obvious when it''s not working than when it is.', '', 'https://www.pitchblende.net/insights/the-cost-of-treating-marketing-like-a-nice-to-have', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630cc2ce847e4ace6e5c3_6a163022095a1d9a12e90550_blog-cost-of-marketing-nice-to-have.png', NULL, 1, 1774224000000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'The Multiplier Effect: Rethinking Brand and Performance', 'Brand and performance aren''t a budget split — they''re a multiplier. When they work together, each dollar in one makes the dollar in the other go further. Here''s how.', '', 'https://www.pitchblende.net/insights/the-multiplier-effect-rethinking-brand-and-performance', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630cc2ce847e4ace6e5e7_6a1630203389b3ca6b490309_blog-the-multiplier-effect.png', NULL, 1, 1776643200000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'Nobody Remembers Efficient. They Remember Remarkable.', 'Efficiency wins quarters. Remarkable wins decades. Why the smartest brands stop optimizing the margin and start spending where memory is made.', '', 'https://www.pitchblende.net/insights/nobody-remembers-efficient-they-remember-remarkable', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a1630cc2ce847e4ace6e5de_6a16301ecc918faeb2208b10_blog-nobody-remembers-efficient.png', NULL, 1, 1777939200000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'marketing'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000)),
  ('link', 'Hiring - Performance Marketing Lead', 'We''re hiring a Performance Marketing Lead to own paid acquisition across search, social, and programmatic for our consultancy clients. Cleveland or NY, hybrid.', '', 'https://www.pitchblende.net/insights/hiring-performance-marketing-lead', '', 'https://cdn.prod.website-files.com/6a162fda8d635e31a20caa65/6a16308650b192cb809e9304_6a16301c7c5a37ac3245794f_blog-hiring-performance-marketing-lead.png', NULL, 1, 1778457600000, 'approved', NULL, (SELECT id FROM briefing_categories WHERE slug = 'leadership'), (strftime('%s','now') * 1000), (strftime('%s','now') * 1000));
